#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int maximumCandies(vector<int> candies, int k ){
    int end = candies[0];
    for(int c : candies) if(c > end) end = c;
    int start = 1;
    int ans = 0;
    while(start <= end){
        int mid = start + (end - start) / 2;
        int allocation = 0;
        for(int c : candies){
            allocation += c/mid;
        }
        if(allocation >= k){
            ans = mid;
            start = mid + 1;
        }else end = mid - 1;;
    }
    return ans;
}

